const LanguageContext = createContext({ language: "en" as LanguageCode, t: (text: string) => text });

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<LanguageCode>("en");
  useEffect(() => {
    const sync = () => {
      const stored = localStorage.getItem("language") as LanguageCode | null;
      setLanguage(stored && labels[stored] ? stored : "en");
    };
    sync(); window.addEventListener("languagechange", sync);
    return () => window.removeEventListener("languagechange", sync);
  }, []);
  return <LanguageContext.Provider value={{ language, t: (text) => addedLanguageExtraLabels[language]?.[text] || addedLanguageLabels[language]?.[text] || profileLabels[language]?.[text] || reviewedUiLabels[language]?.[text] || extraLabels[language][text] || labels[language][text] || text }}>{children}</LanguageContext.Provider>;
}

export const useTranslation = () => useContext(LanguageContext);
